import org.springframework.stereotype.Service;

/** Closes a period, fixing its due-total as it is now: the dues as shown now of the claims whose due-by is in it that counted
 *  at the end of its last day (see {@link Person#countsAtEnd}), each with its late charge, and each person's share of it (a person's unbound OPEN claims dated within one of their holds count in none; a claim whose due is n/a adds nothing).
 *  Used by a close by hand and by the auto close when the sheet's today is changed (see {@link #closeDue}). */
@Service
public class PeriodCloser {

/** A person's due-total for a period: the dues as shown now, late charges included, of their claims whose due-by
 *  (as fixed at creation) falls in it that counted at the end of its last day (see countsAtEnd), leaving out their unbound OPEN claims dated within one of their holds, or all of them once they are retired (a claim whose due is n/a
 *  adds nothing); a closed or soft-closed period gives the figure fixed when it was closed (0.00 for a person added later). */
export function usePersonPeriodDueTotal(sheet: string): (period: Period, personId: string) => bigint {
// The sheet's periods, each with its dates and due-total (the dues as shown now, late charges included, of the claims
// whose date falls in it that counted by the status they had at the end of its last day, leaving out a held person's OPEN claims; a claim whose due is n/a adds nothing), and the form that adds one (a name not
// already on the sheet, a from-date on or before the to-date, not overlapping another period, and an optional cap: a whole number of at
// the dues of their counting OPEN and PENDING claims by age on today (0 to 30 days, 31 to 60, 61 or more; dated after today is 0 to 30),
// whether they are retired and from when, whether they have any hold, and their holds (a person's OPEN claims dated within a hold, unless bound by a
// statement, keep their claimed but their dues leave their figures and the sheet's totals; their other claims still count), their overdue count and
// aliases (sorted as names are compared, comma and space separated), whether they clash (their name or an alias is used by someone else on a sheet of the tree), patrons (each as <name> <share>, sorted by name, comma and space separated; shares split 100.00 equally in the order named, rounded half to even, the remainder to the first-named) and backing (each patron's settled figure — their SETTLED claims dated within the 90 days up to and including today, at their frozen figures — times their share over 100, added up and rounded half to even; 0.00 with none),
// the claim's error. Each claim shows waived (yes or no).
// An OPEN or PENDING claim is held, and released, with the hold toggle: while held and unbound it counts in no live total, as a
// held person's claims (a figure a statement bound it to stays in). A claim in any other status is refused with the claim's
// error. Each claim shows held (yes or no).
// An OPEN or PENDING claim is reminded with the remind button, once per sheet-today: it shows the sheet's today as its reminded
    /** Whether a steward has waived the claim's late charge (once ever): it bears no late charge from then on. */
    private boolean waived;
    public boolean isWaived() { return waived; }
    public void setWaived(boolean waived) { this.waived = waived; }
    /** Whether the claim is held: while OPEN or PENDING and unbound it counts in no live total, as a held person's claims. */
    private boolean held;
  /** Whether a steward has waived the claim's late charge: it bears none from then on, whatever its overdue state. */
  waived?: boolean;
  /** Whether the claim is held: while OPEN or PENDING and unbound it counts in no live total, as a held person's claims. */
  held?: boolean;
/** Whether a claim counts toward claimed: as `countsLive`, except that a hold (the person's or the claim's) does not
 *  take it out — only its due leaves the totals while held. `retiredOn` tells whether its person is retired today. */
export const countsClaimed = (c: Claim, retired: boolean, today: string | undefined) =>
  counts(c) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && retired);
    }
    /** Whether the claim counts toward claimed on the sheet's today: as {@link #countsLive(Claim, LocalDate)}, except that
     *  a hold (the person's or the claim's) does not take it out — only its due leaves the totals while held. */
    public boolean countsClaimed(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isBound() && retiredOn(today));
    }

